console.log("А");
console.log("Б");
console.log("В");
// Вывод: А, Б, В

console.log("Начало");

setTimeout(() => {
    console.log("Таймер сработал"); // Выполнится ПОЗЖЕ
}, 2000);

console.log("Конец");
// Вывод: Начало, Конец, Таймер сработал

console.log("1");

setTimeout(() => console.log("2"), 0);    // Макрозадача

Promise.resolve()
    .then(() => console.log("3"))         // Микрозадача 1
    .then(() => console.log("4"));        // Микрозадача 2

console.log("5");

// Вывод: 1, 5, 3, 4, 2

blocks.text:
1. Объясните порядок вывода: console.log("A"); setTimeout(() => console.log("B"), 0); console.log("C");
2. Напишите пример, где setTimeout(fn, 1000) выполняется раньше setTimeout(fn, 0).
3. Объясните, почему setTimeout(() => {}, 0) не выполняется мгновенно.
